//! Port of `test/cross-provider-handoff.test.ts`.
//!
//! Tests that contexts generated by one provider/model can be consumed by
//! another (tool call ID formats, thinking block transformation, message
//! formats). The TS `beforeAll` fixture generation runs once per test binary
//! through a shared `OnceCell`; both cases make real requests, so they are
//! `#[ignore]`d. TS `describe.skipIf(!hasAnyApiKey())` becomes a check that
//! fails with a clear message when no provider credential is set. TS
//! `resolveApiKey` (`test/oauth.ts`) reads `PI_TEST_<PROVIDER>_TOKEN`.

mod anthropic_support;
mod openai_responses_support;

use std::sync::{Arc, Mutex, PoisonError};
use std::time::{SystemTime, UNIX_EPOCH};

use anthropic_support::resolve_test_api_key;
