use eukhe_pi_ai::types::{OnPayload, ProviderHeaders, SimpleStreamOptions};
use eukhe_types::pi_ai::{
    AssistantContentBlock, AssistantMessage, Context, IndexMap, JsonValue, Message, Model,
    StopReason, ThinkingLevel,
};
use openai_responses_support::azure::has_azure_openai_credentials;
use serde_json::json;
use tokio::sync::OnceCell;

/// `Date.now()`.
fn now() -> u64 {
    let elapsed = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .expect("clock after epoch");
    u64::try_from(elapsed.as_millis()).expect("epoch millis fit u64")
}

fn env_value(name: &str) -> Option<String> {
    std::env::var(name).ok().filter(|value| !value.is_empty())
}

/// TS `testTool`: `double_number` with a described `Type.Number`.
fn test_tool() -> JsonValue {
    json!({
        "name": "double_number",
        "description": "Doubles a number and returns the result",
        "parameters": {
            "type": "object",
            "properties": {
                "value": { "description": "A number to double", "type": "number" },
            },
            "required": ["value"],
        },
    })
}

/// TS `ProviderModelPair`.
struct ProviderModelPair {
    provider: &'static str,
    model: &'static str,
    label: &'static str,
    api_override: Option<&'static str>,
    upstream_api_key_env: Option<&'static str>,
}

const fn pair(
    provider: &'static str,
    model: &'static str,
    label: &'static str,
) -> ProviderModelPair {
    ProviderModelPair {
        provider,
        model,
        label,
        api_override: None,
        upstream_api_key_env: None,
    }
}

const fn with_api_override(mut pair: ProviderModelPair, api: &'static str) -> ProviderModelPair {
    pair.api_override = Some(api);
    pair
}

const fn with_upstream_api_key_env(
    mut pair: ProviderModelPair,
    env: &'static str,
) -> ProviderModelPair {
    pair.upstream_api_key_env = Some(env);
    pair
}

